#!/usr/bin/env python3
"""Idempotent replay of freeze enforced_reduced_packages AppOps.

Only write: cmd appops set --user 0 PKG RUN_ANY_IN_BACKGROUND ignore
Optional:   cmd appops write-settings  (only if this run actually wrote)
Never: pm disable/enable/uninstall, deviceidle whitelist, netpolicy,
       settings put, compile, reboot, kill-server.
"""
from __future__ import annotations

import json
import os
import subprocess
import sys
from datetime import datetime
from pathlib import Path

ADB_FALLBACK = r"C:\Users\hzq00\Downloads\platform-tools-latest-windows\platform-tools\adb.exe"
SERIAL = "AVNS023705001888"
DESIRED = Path(r"C:\Users\hzq00\Documents\Codex\2026-08-23\ni-j\outputs\HONOR_DESIRED_STATE.stage3.20260823.json")
LOG_DIR = Path(r"C:\Users\hzq00\Documents\Codex\logs")
EXPECTED_BRAND = "HONOR"
EXPECTED_MODEL = "VER-AN10"


class ReplayError(SystemExit):
    pass


def now_stamp() -> str:
    return datetime.now().strftime("%Y%m%d_%H%M%S")


def find_adb() -> str:
    env = os.environ.get("ANDROID_HOME") or os.environ.get("ANDROID_SDK_ROOT")
    candidates = [ADB_FALLBACK]
    if env:
        candidates.append(str(Path(env) / "platform-tools" / "adb.exe"))
    for c in candidates:
        if Path(c).is_file():
            return c
    raise ReplayError("adb not found")


def adb_base(adb: str, transport: str) -> list[str]:
    cmd = [adb]
    if transport:
        cmd.extend(["-L", transport])
    cmd.extend(["-s", SERIAL])
    return cmd


def run(cmd: list[str], timeout: int = 30) -> subprocess.CompletedProcess:
    return subprocess.run(cmd, capture_output=True, timeout=timeout)


def decode(p: subprocess.CompletedProcess) -> tuple[int, str, str]:
    out = (p.stdout or b"").decode("utf-8", "replace")
    err = (p.stderr or b"").decode("utf-8", "replace")
    return p.returncode, out, err


def devices_on(adb: str, transport: str | None) -> list[str]:
    cmd = [adb]
    if transport:
        cmd.extend(["-L", transport])
    cmd.append("devices")
    p = run(cmd, timeout=12)
    rc, out, err = decode(p)
    if rc != 0:
        return []
    found = []
    for line in out.splitlines()[1:]:
        parts = line.split()
        if len(parts) >= 2 and parts[1] == "device":
            found.append(parts[0])
    return found


def pick_transport(adb: str) -> str:
    if SERIAL in devices_on(adb, "tcp:5038"):
        return "tcp:5038"
    if SERIAL in devices_on(adb, None):
        return ""
    raise ReplayError(
        "device AVNS023705001888 not visible on tcp:5038 or default adb. "
        "Will not kill/restart adb servers."
    )


def shell(adb: str, transport: str, *args: str, timeout: int = 30) -> tuple[int, str, str]:
    cmd = adb_base(adb, transport) + ["shell", *args]
    return decode(run(cmd, timeout=timeout))


def load_reduced(path: Path) -> list[str]:
    if not path.is_file():
        raise ReplayError(f"desired-state missing: {path}")
    doc = json.loads(path.read_text(encoding="utf-8"))
    rows = doc.get("enforced_reduced_packages")
    if not isinstance(rows, list) or not rows:
        raise ReplayError("enforced_reduced_packages missing or empty")
    pkgs: list[str] = []
    seen: set[str] = set()
    for item in rows:
        if isinstance(item, str):
            name = item.strip()
        elif isinstance(item, dict):
            name = str(item.get("package") or "").strip()
        else:
            raise ReplayError(f"bad reduced entry: {item!r}")
        if not name:
            raise ReplayError(f"empty package in {item!r}")
        if name in seen:
            continue
        seen.add(name)
        pkgs.append(name)
    return pkgs


def parse_appops_mode(text: str) -> str:
    t = text.strip()
    if "No UID" in t or "Unknown package" in t or "Can't find package" in t:
        return "MISSING"
    if "RUN_ANY_IN_BACKGROUND: ignore" in t or t.endswith(": ignore"):
        return "ignore"
    if "RUN_ANY_IN_BACKGROUND: allow" in t or t.endswith(": allow"):
        return "allow"
    if "RUN_ANY_IN_BACKGROUND: deny" in t:
        return "deny"
    if "RUN_ANY_IN_BACKGROUND: default" in t or "Default mode: allow" in t:
        return "allow"
    if not t:
        return "EMPTY"
    return "OTHER:" + t.splitlines()[0][:80]


def installed_user0(adb: str, transport: str, pkg: str) -> bool:
    rc, out, err = shell(adb, transport, "pm", "path", "--user", "0", pkg, timeout=20)
    text = out + err
    return rc == 0 and "package:" in text


def supports_write_settings(adb: str, transport: str) -> bool:
    rc, out, err = shell(adb, transport, "cmd", "appops", "help", timeout=20)
    return "write-settings" in (out + err)


def gate_device(adb: str, transport: str) -> dict:
    checks = {
        "brand": ("getprop", "ro.product.brand"),
        "model": ("getprop", "ro.product.model"),
        "boot": ("getprop", "sys.boot_completed"),
        "user": ("am", "get-current-user"),
        "display": ("getprop", "ro.build.display.id"),
        "fingerprint": ("getprop", "ro.build.fingerprint"),
    }
    info = {}
    for key, args in checks.items():
        rc, out, err = shell(adb, transport, *args, timeout=15)
        info[key] = out.strip()
        if rc != 0:
            raise ReplayError(f"gate {key} failed: {err or out}")
    if info["brand"].upper() != EXPECTED_BRAND:
        raise ReplayError(f"brand mismatch {info['brand']}")
    if info["model"] != EXPECTED_MODEL:
        raise ReplayError(f"model mismatch {info['model']}")
    if info["boot"] != "1":
        raise ReplayError(f"boot_completed={info['boot']}")
    if info["user"] != "0":
        raise ReplayError(f"current user={info['user']} (need 0)")
    return info


def replay() -> dict:
    LOG_DIR.mkdir(parents=True, exist_ok=True)
    ts = now_stamp()
    log_path = LOG_DIR / f"HONOR_Reapply_Reduced_{ts}.log"
    lines: list[str] = []

    def log(msg: str) -> None:
        lines.append(msg)
        print(msg)

    adb = find_adb()
    transport = pick_transport(adb)
    transport_label = transport or "default"
    log(f"ts={datetime.now().isoformat(timespec='seconds')}")
    log(f"adb={adb}")
    log(f"transport={transport_label}")
    log(f"serial={SERIAL}")
    log(f"desired={DESIRED}")

    info = gate_device(adb, transport)
    for k, v in info.items():
        log(f"gate.{k}={v}")

    pkgs = load_reduced(DESIRED)
    log(f"desired_count={len(pkgs)}")

    write_settings_ok = supports_write_settings(adb, transport)
    log(f"write_settings_supported={write_settings_ok}")

    already: list[str] = []
    changed: list[str] = []
    missing: list[str] = []
    failed: list[dict] = []
    writes = 0

    for pkg in pkgs:
        if not installed_user0(adb, transport, pkg):
            missing.append(pkg)
            log(f"MISSING {pkg}")
            continue
        rc, out, err = shell(
            adb, transport, "cmd", "appops", "get", "--user", "0", pkg, "RUN_ANY_IN_BACKGROUND"
        )
        mode = parse_appops_mode(out + err)
        if mode == "ignore":
            already.append(pkg)
            log(f"NOOP {pkg}")
            continue
        if mode == "MISSING":
            missing.append(pkg)
            log(f"MISSING {pkg} (appops)")
            continue
        rc2, out2, err2 = shell(
            adb, transport, "cmd", "appops", "set", "--user", "0", pkg, "RUN_ANY_IN_BACKGROUND", "ignore"
        )
        writes += 1
        rc3, out3, err3 = shell(
            adb, transport, "cmd", "appops", "get", "--user", "0", pkg, "RUN_ANY_IN_BACKGROUND"
        )
        after = parse_appops_mode(out3 + err3)
        if rc2 == 0 and after == "ignore":
            changed.append(pkg)
            log(f"CHANGED {pkg} {mode}->{after}")
        else:
            rec = {
                "package": pkg,
                "before": mode,
                "set_rc": rc2,
                "set_err": (err2 or out2).strip()[:200],
                "after": after,
            }
            failed.append(rec)
            log(f"FAILED {pkg} {rec}")

    write_settings_ran = False
    if writes and write_settings_ok:
        rcw, outw, errw = shell(adb, transport, "cmd", "appops", "write-settings")
        write_settings_ran = rcw == 0
        log(f"write-settings rc={rcw} out={(outw or errw).strip()[:200]}")
        if rcw != 0:
            failed.append({"package": "*", "action": "write-settings", "rc": rcw, "err": (errw or outw).strip()[:200]})
    elif writes and not write_settings_ok:
        log("write-settings skipped: not in help")
    else:
        log("write-settings skipped: no writes")

    final = {}
    for pkg in pkgs:
        if pkg in missing:
            final[pkg] = "MISSING"
            continue
        rc, out, err = shell(
            adb, transport, "cmd", "appops", "get", "--user", "0", pkg, "RUN_ANY_IN_BACKGROUND"
        )
        final[pkg] = parse_appops_mode(out + err)

    result = {
        "desired": str(DESIRED),
        "desired_count": len(pkgs),
        "already_ignore": already,
        "changed_to_ignore": changed,
        "missing": missing,
        "failed": failed,
        "writes": writes,
        "write_settings_supported": write_settings_ok,
        "write_settings_ran": write_settings_ran,
        "transport": transport_label,
        "display": info.get("display"),
        "final": final,
        "log": str(log_path),
    }
    log(f"SUMMARY already={len(already)} changed={len(changed)} missing={len(missing)} failed={len(failed)} writes={writes}")
    log("RESULT_JSON " + json.dumps(
        {k: result[k] for k in result if k != "final"}, ensure_ascii=False
    ))
    log_path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    result_json = LOG_DIR / f"HONOR_Reapply_Reduced_{ts}.json"
    result_json.write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
    print(json.dumps({
        "desired_count": len(pkgs),
        "already_ignore": len(already),
        "changed_to_ignore": len(changed),
        "missing": missing,
        "failed": failed,
        "writes": writes,
        "write_settings_ran": write_settings_ran,
        "log": str(log_path),
        "result_json": str(result_json),
    }, ensure_ascii=False, indent=2))
    if failed:
        raise ReplayError(f"replay failed: {failed}")
    return result


if __name__ == "__main__":
    try:
        replay()
    except ReplayError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        sys.exit(2)
    except subprocess.TimeoutExpired as exc:
        print(f"ERROR: timeout {exc}", file=sys.stderr)
        sys.exit(3)

